"use client";

import type { IdResult } from "../../lib/gov-ids";
import {
  type DematResult,
  type IsinResult,
  type MicrResult,
  type SwiftResult,
  type UtrResult,
  validateCkyc,
  validateDemat,
  validateIsin,
  validateLei,
  validateMicr,
  validateSwift,
  validateUtr,
} from "../../lib/market-ids";
import { IdentifierInput, type IdentifierInputProps } from "./identifier-input";

type WrapperProps<T extends { valid: boolean; error?: { message: string } }> =
  Omit<IdentifierInputProps<T>, "validate" | "transform" | "badge">;

const digits = (max: number) => (raw: string) =>
  raw.replace(/\D/g, "").slice(0, max);
const alnum = (max: number) => (raw: string) =>
  raw
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, "")
    .slice(0, max);

/**
 * LEI — 20 characters ending in an ISO 7064 MOD 97-10 check.
 * One of the few Indian-form identifiers with a genuinely public checksum.
 */
export function LEIInput(props: WrapperProps<IdResult>) {
  return (
    <IdentifierInput<IdResult>
      placeholder="5493001KJTIIGC8Y1R12"
      tracking="tracking-[0.04em]"
      {...props}
      validate={validateLei}
      transform={alnum(20)}
    />
  );
}

/** ISIN — 12 characters with an ISO 6166 check digit. Badges Indian securities. */
export function ISINInput(props: WrapperProps<IsinResult>) {
  return (
    <IdentifierInput<IsinResult>
      placeholder="INE002A01018"
      tracking="tracking-[0.1em]"
      {...props}
      validate={validateIsin}
      transform={alnum(12)}
      badge={(result) => (result.indian ? "Indian security" : result.country)}
    />
  );
}

/** MICR — the nine digits along the bottom of a cheque. */
export function MICRInput(props: WrapperProps<MicrResult>) {
  return (
    <IdentifierInput<MicrResult>
      placeholder="560002007"
      tracking="tracking-[0.18em]"
      {...props}
      validate={validateMicr}
      transform={digits(9)}
    />
  );
}

/** Demat account — badges whether it's NSDL or CDSL. */
export function DematInput(props: WrapperProps<DematResult>) {
  return (
    <IdentifierInput<DematResult>
      placeholder="IN30012345678901"
      tracking="tracking-[0.08em]"
      {...props}
      validate={validateDemat}
      transform={alnum(16)}
      badge={(result) => result.depository}
    />
  );
}

/** SWIFT/BIC — 8 characters for head office, 11 for a specific branch. */
export function SWIFTInput(props: WrapperProps<SwiftResult>) {
  return (
    <IdentifierInput<SwiftResult>
      placeholder="HDFCINBB"
      tracking="tracking-[0.14em]"
      {...props}
      validate={validateSwift}
      transform={alnum(11)}
      badge={(result) => (result.branch ? "Branch" : "Head office")}
    />
  );
}

/** CKYC — the Central KYC Registry number, 14 digits. */
export function CKYCInput(props: WrapperProps<IdResult>) {
  return (
    <IdentifierInput<IdResult>
      placeholder="12345678901234"
      tracking="tracking-[0.12em]"
      {...props}
      validate={validateCkyc}
      transform={digits(14)}
    />
  );
}

/** UTR — infers the payment rail from length, which is what support needs. */
export function UTRInput(props: WrapperProps<UtrResult>) {
  return (
    <IdentifierInput<UtrResult>
      placeholder="123456789012"
      tracking="tracking-[0.1em]"
      {...props}
      validate={validateUtr}
      transform={alnum(22)}
      badge={(result) => result.rail}
    />
  );
}

export type LEIInputProps = WrapperProps<IdResult>;
export type ISINInputProps = WrapperProps<IsinResult>;
export type MICRInputProps = WrapperProps<MicrResult>;
export type DematInputProps = WrapperProps<DematResult>;
export type SWIFTInputProps = WrapperProps<SwiftResult>;
export type CKYCInputProps = WrapperProps<IdResult>;
export type UTRInputProps = WrapperProps<UtrResult>;

"use client";

import { type ClassValue, clsx } from "clsx";
import { CircleAlert, Info } from "lucide-react";
import * as React from "react";
import { twMerge } from "tailwind-merge";

/**
 * Shared by every bharat-ui field. Defined here rather than imported from a
 * project's `@/lib/utils` so that installing a component can never overwrite
 * the consumer's own utils file.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export type FieldTone = "error" | "hint" | "muted";

export interface FieldProps {
  id: string;
  /** Id of the element holding the message; wire this into aria-describedby. */
  messageId: string;
  label?: string;
  /** Resolved message text — an error, a warning, or the fallback description. */
  message?: string;
  tone?: FieldTone;
  className?: string;
  children: React.ReactNode;
}

/** Label + control + message, with the aria plumbing already correct. */
export function Field({
  id,
  messageId,
  label,
  message,
  tone = "muted",
  className,
  children,
}: FieldProps) {
  return (
    <div className={cn("w-full", className)}>
      {label && (
        <label htmlFor={id} className="mb-1.5 block text-sm font-medium">
          {label}
        </label>
      )}

      {children}

      {message && (
        <p
          id={messageId}
          // Only errors interrupt a screen reader; hints are read on focus.
          role={tone === "error" ? "alert" : undefined}
          className={cn(
            "mt-1.5 flex items-start gap-1.5 text-xs",
            tone === "error"
              ? "text-red-600 dark:text-red-400"
              : "text-neutral-500 dark:text-neutral-400",
          )}
        >
          {tone === "error" ? (
            <CircleAlert className="mt-px size-3.5 shrink-0" aria-hidden />
          ) : tone === "hint" ? (
            <Info className="mt-px size-3.5 shrink-0" aria-hidden />
          ) : null}
          {message}
        </p>
      )}
    </div>
  );
}

/** Border/ring classes shared by every text control, keyed on validity. */
export function controlClasses(state: {
  error?: boolean;
  success?: boolean;
}): string {
  return cn(
    "h-10 w-full rounded-lg border bg-transparent px-3 py-2 font-mono text-sm outline-none transition",
    "placeholder:font-sans placeholder:text-neutral-400 dark:placeholder:text-neutral-600",
    "disabled:cursor-not-allowed disabled:opacity-50",
    "focus-visible:ring-[3px]",
    state.error
      ? "border-red-500 focus-visible:ring-red-500/20"
      : state.success
        ? "border-emerald-500 focus-visible:ring-emerald-500/20"
        : "border-neutral-300 focus-visible:border-neutral-900 focus-visible:ring-neutral-900/10 dark:border-neutral-700 dark:focus-visible:border-neutral-300 dark:focus-visible:ring-neutral-100/10",
  );
}

export interface ValidationLike {
  valid: boolean;
  error?: { message: string };
}

/**
 * The controlled/uncontrolled + touched + report-upward logic every field here
 * needs. Kept in one place so all of them behave identically: errors appear on
 * blur by default, then update live once the user has been warned.
 */
export function useFieldState<T extends ValidationLike>(options: {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onValidationChange?: (result: T) => void;
  validate: (raw: string) => T;
  /** Optional input mask applied on every keystroke. */
  transform?: (raw: string) => string;
  validateOn?: "blur" | "change";
}) {
  const {
    value: controlled,
    defaultValue = "",
    onValueChange,
    onValidationChange,
    validate,
    transform,
    validateOn = "blur",
  } = options;

  const isControlled = controlled !== undefined;
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue);
  const value = isControlled ? controlled : uncontrolled;
  const [touched, setTouched] = React.useState(false);

  const result = React.useMemo(() => validate(value), [value, validate]);

  // Report upward only when the outcome actually changes, so consumers can put
  // setState directly in the callback without a render loop.
  const lastReported = React.useRef<string>("");
  React.useEffect(() => {
    const key = JSON.stringify(result);
    if (key === lastReported.current) return;
    lastReported.current = key;
    onValidationChange?.(result);
  }, [result, onValidationChange]);

  const setValue = React.useCallback(
    (next: string) => {
      const masked = transform ? transform(next) : next;
      if (!isControlled) setUncontrolled(masked);
      onValueChange?.(masked);
    },
    [isControlled, onValueChange, transform],
  );

  const shouldValidate = validateOn === "change" || touched;
  const error =
    shouldValidate && value.trim() !== "" ? result.error?.message : undefined;

  return {
    value,
    setValue,
    result,
    touched,
    markTouched: () => setTouched(true),
    error,
    success: result.valid,
  };
}

/** Small right-aligned badge inside a control (bank name, entity type, …). */
export function FieldBadge({ children }: { children: React.ReactNode }) {
  return (
    <span className="pointer-events-none absolute right-2 top-1/2 flex max-w-[45%] -translate-y-1/2 items-center gap-1 truncate rounded-full bg-emerald-500/10 px-2 py-0.5 text-xs font-medium text-emerald-700 dark:text-emerald-400">
      {children}
    </span>
  );
}

"use client";

import * as React from "react";

import {
  cn,
  controlClasses,
  Field,
  FieldBadge,
  useFieldState,
  type ValidationLike,
} from "./field";

export interface IdentifierInputProps<T extends ValidationLike>
  extends Omit<
    React.ComponentProps<"input">,
    "value" | "defaultValue" | "onChange" | "type"
  > {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onValidationChange?: (result: T) => void;
  validateOn?: "blur" | "change";
  validate: (raw: string) => T;
  /** Input mask applied on every keystroke. */
  transform?: (raw: string) => string;
  /** Derives the right-hand badge from a valid result. */
  badge?: (result: T) => string | undefined;
  label?: string;
  description?: string;
  containerClassName?: string;
  /** Extra letter-spacing suits fixed-format identifiers. */
  tracking?: string;
}

/**
 * The shared body of every fixed-format identifier field. The specific
 * components (PAN, TAN, CIN, …) are thin wrappers that supply a validator, a
 * mask and a placeholder — everything else behaves identically by construction.
 */
export function IdentifierInput<T extends ValidationLike>({
  value: controlledValue,
  defaultValue = "",
  onValueChange,
  onValidationChange,
  validateOn = "blur",
  validate,
  transform,
  badge,
  label,
  description,
  className,
  containerClassName,
  tracking = "tracking-[0.12em]",
  id,
  onBlur,
  ...props
}: IdentifierInputProps<T>) {
  const reactId = React.useId();
  const inputId = id ?? `id-${reactId}`;
  const messageId = `${inputId}-message`;

  const field = useFieldState<T>({
    value: controlledValue,
    defaultValue,
    onValueChange,
    onValidationChange,
    validate,
    transform,
    validateOn,
  });

  const badgeText =
    badge && field.result.valid ? badge(field.result) : undefined;

  return (
    <Field
      id={inputId}
      messageId={messageId}
      label={label}
      message={field.error ?? description}
      tone={field.error ? "error" : "muted"}
      className={containerClassName}
    >
      <div className="relative">
        <input
          {...props}
          id={inputId}
          type="text"
          autoComplete="off"
          autoCapitalize="characters"
          autoCorrect="off"
          spellCheck={false}
          value={field.value}
          onChange={(event) => field.setValue(event.target.value)}
          onBlur={(event) => {
            field.markTouched();
            onBlur?.(event);
          }}
          aria-invalid={Boolean(field.error)}
          aria-describedby={messageId}
          className={cn(
            controlClasses({
              error: Boolean(field.error),
              success: field.success,
            }),
            tracking,
            badgeText && "pr-36",
            className,
          )}
        />
        {badgeText && <FieldBadge>{badgeText}</FieldBadge>}
      </div>
    </Field>
  );
}

/**
 * Capital-markets and banking identifiers.
 *
 * Two of these carry genuinely public checksums, which is rare for Indian
 * forms and worth using:
 *   - LEI  — ISO 17442, checked with ISO 7064 MOD 97-10.
 *   - ISIN — ISO 6166, a Luhn variant over letter-expanded digits.
 *
 * The rest (MICR, DEMAT, CKYC, UTR, SWIFT) have no check digit, so they are
 * validated structurally only.
 */

import type { IdResult } from "./gov-ids";

function bad<E extends string>(
  code: E,
  message: string,
  normalized: string,
): IdResult<E> {
  return { valid: false, normalized, error: { code, message } };
}

const upper = (input: string) => input.replace(/[\s-]/g, "").toUpperCase();

/** A=10 … Z=35, digits unchanged. Shared by the LEI and ISIN algorithms. */
function expandAlphanumerics(value: string): string {
  let out = "";
  for (const char of value) {
    if (char >= "0" && char <= "9") out += char;
    else out += String(char.charCodeAt(0) - 55);
  }
  return out;
}

/** ISO 7064 MOD 97-10 over an arbitrarily long digit string. */
function mod97(digits: string): number {
  let remainder = 0;
  for (const digit of digits) {
    remainder = (remainder * 10 + Number(digit)) % 97;
  }
  return remainder;
}

/* ── LEI ─────────────────────────────────────────────────────────────────── */

const LEI_RE = /^[0-9A-Z]{18}[0-9]{2}$/;

export type LeiErrorCode =
  | "empty"
  | "wrong_length"
  | "bad_shape"
  | "bad_checksum";

/**
 * Legal Entity Identifier — 20 characters, the last two being an ISO 7064
 * MOD 97-10 check. Required for anyone trading derivatives or doing large
 * cross-border transfers, and increasingly asked for in Indian KYB flows.
 */
export function validateLei(input: string): IdResult<LeiErrorCode> {
  const lei = upper(input);
  if (!input.trim()) return bad("empty", "Enter an LEI.", lei);
  if (lei.length !== 20) {
    return bad(
      "wrong_length",
      `An LEI is 20 characters — ${lei.length} so far.`,
      lei,
    );
  }
  if (!LEI_RE.test(lei)) {
    return bad(
      "bad_shape",
      "An LEI is 18 alphanumerics then two check digits.",
      lei,
    );
  }
  if (mod97(expandAlphanumerics(lei)) !== 1) {
    return bad(
      "bad_checksum",
      "That LEI failed its checksum — check for a typo.",
      lei,
    );
  }
  return { valid: true, normalized: lei };
}

/* ── ISIN ────────────────────────────────────────────────────────────────── */

const ISIN_RE = /^[A-Z]{2}[0-9A-Z]{9}[0-9]$/;

export type IsinErrorCode =
  | "empty"
  | "wrong_length"
  | "bad_shape"
  | "bad_checksum";

export interface IsinResult extends IdResult<IsinErrorCode> {
  /** Two-letter ISO country code — `IN` for Indian securities. */
  country?: string;
  /** True when this is an Indian security. */
  indian?: boolean;
}

/** Luhn over the letter-expanded body, as ISO 6166 specifies. */
export function isinCheckDigit(first11: string): number | null {
  if (first11.length !== 11) return null;
  const digits = expandAlphanumerics(first11);

  let sum = 0;
  let double = true; // ISO 6166 doubles starting from the rightmost body digit
  for (let i = digits.length - 1; i >= 0; i--) {
    let value = Number(digits[i]);
    if (double) {
      value *= 2;
      if (value > 9) value -= 9;
    }
    sum += value;
    double = !double;
  }
  return (10 - (sum % 10)) % 10;
}

/**
 * International Securities Identification Number. Indian equities and mutual
 * funds all carry one (`INE...`, `INF...`), so any broking or wealth product
 * ends up validating these.
 */
export function validateIsin(input: string): IsinResult {
  const isin = upper(input);
  if (!input.trim()) return bad("empty", "Enter an ISIN.", isin);
  if (isin.length !== 12) {
    return bad(
      "wrong_length",
      `An ISIN is 12 characters — ${isin.length} so far.`,
      isin,
    );
  }
  if (!ISIN_RE.test(isin)) {
    return bad("bad_shape", "An ISIN looks like INE002A01018.", isin);
  }

  const expected = isinCheckDigit(isin.slice(0, 11));
  if (expected === null || expected !== Number(isin[11])) {
    return bad("bad_checksum", "That ISIN failed its check digit.", isin);
  }

  const country = isin.slice(0, 2);
  return { valid: true, normalized: isin, country, indian: country === "IN" };
}

/* ── MICR ────────────────────────────────────────────────────────────────── */

export type MicrErrorCode = "empty" | "not_digits" | "wrong_length";

export interface MicrResult extends IdResult<MicrErrorCode> {
  cityCode?: string;
  bankCode?: string;
  branchCode?: string;
}

/**
 * The nine digits along the bottom of a cheque: city, bank, branch. No check
 * digit — the magnetic ink is the integrity mechanism, not the number.
 */
export function validateMicr(input: string): MicrResult {
  const micr = input.replace(/\D/g, "");
  if (!input.trim()) return bad("empty", "Enter a MICR code.", micr);
  if (/[^\d\s-]/.test(input))
    return bad("not_digits", "A MICR code is digits only.", micr);
  if (micr.length !== 9) {
    return bad(
      "wrong_length",
      `A MICR code is 9 digits — ${micr.length} so far.`,
      micr,
    );
  }
  return {
    valid: true,
    normalized: micr,
    cityCode: micr.slice(0, 3),
    bankCode: micr.slice(3, 6),
    branchCode: micr.slice(6),
  };
}

/* ── Demat account ───────────────────────────────────────────────────────── */

export type DematErrorCode = "empty" | "wrong_length" | "bad_shape";

export interface DematResult extends IdResult<DematErrorCode> {
  /** NSDL accounts start `IN`; CDSL accounts are 16 digits. */
  depository?: "NSDL" | "CDSL";
}

export function validateDemat(input: string): DematResult {
  const id = upper(input);
  if (!input.trim()) return bad("empty", "Enter a demat account number.", id);
  if (id.length !== 16) {
    return bad(
      "wrong_length",
      `A demat account is 16 characters — ${id.length} so far.`,
      id,
    );
  }
  if (/^IN\d{14}$/.test(id)) {
    return { valid: true, normalized: id, depository: "NSDL" };
  }
  if (/^\d{16}$/.test(id)) {
    return { valid: true, normalized: id, depository: "CDSL" };
  }
  return bad(
    "bad_shape",
    "NSDL accounts start with IN; CDSL accounts are 16 digits.",
    id,
  );
}

/* ── SWIFT / BIC ─────────────────────────────────────────────────────────── */

const SWIFT_RE = /^[A-Z]{4}[A-Z]{2}[0-9A-Z]{2}([0-9A-Z]{3})?$/;

export type SwiftErrorCode = "empty" | "wrong_length" | "bad_shape";

export interface SwiftResult extends IdResult<SwiftErrorCode> {
  bankCode?: string;
  countryCode?: string;
  branch?: string;
}

/** 8 or 11 characters. 11 means a specific branch; 8 means head office. */
export function validateSwift(input: string): SwiftResult {
  const code = upper(input);
  if (!input.trim()) return bad("empty", "Enter a SWIFT/BIC code.", code);
  if (code.length !== 8 && code.length !== 11) {
    return bad("wrong_length", "A SWIFT code is 8 or 11 characters.", code);
  }
  if (!SWIFT_RE.test(code)) {
    return bad(
      "bad_shape",
      "A SWIFT code looks like HDFCINBB or HDFCINBBXXX.",
      code,
    );
  }
  return {
    valid: true,
    normalized: code,
    bankCode: code.slice(0, 4),
    countryCode: code.slice(4, 6),
    branch: code.length === 11 ? code.slice(8) : undefined,
  };
}

/* ── CKYC ────────────────────────────────────────────────────────────────── */

export type CkycErrorCode = "empty" | "not_digits" | "wrong_length";

/** Central KYC Registry number — 14 digits, no public check digit. */
export function validateCkyc(input: string): IdResult<CkycErrorCode> {
  const id = input.replace(/\D/g, "");
  if (!input.trim()) return bad("empty", "Enter a CKYC number.", id);
  if (/[^\d\s-]/.test(input))
    return bad("not_digits", "A CKYC number is digits only.", id);
  if (id.length !== 14) {
    return bad(
      "wrong_length",
      `A CKYC number is 14 digits — ${id.length} so far.`,
      id,
    );
  }
  return { valid: true, normalized: id };
}

/* ── UTR ─────────────────────────────────────────────────────────────────── */

export type UtrErrorCode = "empty" | "bad_shape" | "bad_length";

export interface UtrResult extends IdResult<UtrErrorCode> {
  /** Inferred from length — a hint for support flows, not a guarantee. */
  rail?: "UPI" | "IMPS" | "NEFT / RTGS";
}

/**
 * Unique Transaction Reference — what a user reads off their statement when
 * payment support asks "what's the UTR?". Length varies by rail, so we infer
 * rather than enforce.
 */
export function validateUtr(input: string): UtrResult {
  const utr = upper(input);
  if (!input.trim()) return bad("empty", "Enter a UTR.", utr);
  if (!/^[0-9A-Z]+$/.test(utr)) {
    return bad("bad_shape", "A UTR is letters and digits only.", utr);
  }

  const rail =
    utr.length === 12
      ? ("UPI" as const)
      : utr.length === 16
        ? ("IMPS" as const)
        : utr.length === 22
          ? ("NEFT / RTGS" as const)
          : undefined;

  if (!rail) {
    return bad(
      "bad_length",
      "A UTR is 12, 16 or 22 characters depending on the rail.",
      utr,
    );
  }
  return { valid: true, normalized: utr, rail };
}

/**
 * Government photo-ID identifiers used in Indian KYC: Voter ID (EPIC),
 * driving licence, and passport.
 *
 * None of these carry a public checksum, so everything here is structural.
 * Real verification means the issuing authority's API — ECI, Parivahan/Sarathi,
 * or the Passport Seva portal respectively.
 */

import { RTO_STATE_CODES } from "./vehicle";

export interface IdResult<E extends string = string> {
  valid: boolean;
  normalized: string;
  error?: { code: E; message: string };
}

function ok<E extends string>(normalized: string): IdResult<E> {
  return { valid: true, normalized };
}

function bad<E extends string>(
  code: E,
  message: string,
  normalized: string,
): IdResult<E> {
  return { valid: false, normalized, error: { code, message } };
}

const upper = (input: string) => input.replace(/[\s-]/g, "").toUpperCase();

/* ── Voter ID (EPIC) ─────────────────────────────────────────────────────── */

const EPIC_RE = /^[A-Z]{3}[0-9]{7}$/;

export type VoterIdErrorCode = "empty" | "wrong_length" | "bad_shape";

/**
 * EPIC numbers are three letters (the Functional Constituency code) followed by
 * seven digits. Older cards used other shapes, but every card issued since the
 * 2000s follows this one.
 */
export function validateVoterId(input: string): IdResult<VoterIdErrorCode> {
  const id = upper(input);
  if (!input.trim()) return bad("empty", "Enter a Voter ID number.", id);
  if (id.length !== 10) {
    return bad(
      "wrong_length",
      `An EPIC number is 10 characters — ${id.length} so far.`,
      id,
    );
  }
  if (!EPIC_RE.test(id)) {
    return bad(
      "bad_shape",
      "A Voter ID looks like ABC1234567 — three letters, seven digits.",
      id,
    );
  }
  return ok(id);
}

/* ── Driving licence ─────────────────────────────────────────────────────── */

const DL_RE = /^([A-Z]{2})(\d{2})(\d{4})(\d{7})$/;

export type LicenceErrorCode =
  | "empty"
  | "wrong_length"
  | "bad_shape"
  | "unknown_state"
  | "bad_year";

export interface LicenceResult extends IdResult<LicenceErrorCode> {
  stateCode?: string;
  state?: string;
  rtoCode?: string;
  year?: number;
}

/**
 * Format is `SSRRYYYYNNNNNNN` — state, RTO office, year of issue, serial.
 * Printed with spaces or hyphens in practice, so we strip them first.
 */
export function validateDrivingLicence(input: string): LicenceResult {
  const dl = upper(input);
  if (!input.trim()) return bad("empty", "Enter a driving licence number.", dl);
  if (dl.length !== 15) {
    return bad(
      "wrong_length",
      `A licence number is 15 characters — ${dl.length} so far.`,
      dl,
    );
  }

  const match = DL_RE.exec(dl);
  if (!match) {
    return bad(
      "bad_shape",
      "A licence looks like MH1220110012345 — state, RTO, year, serial.",
      dl,
    );
  }

  const [, stateCode, rtoCode, yearStr] = match;
  const state = RTO_STATE_CODES[stateCode];
  if (!state)
    return bad(
      "unknown_state",
      `“${stateCode}” isn't a state code we recognise.`,
      dl,
    );

  const year = Number(yearStr);
  const thisYear = new Date().getFullYear();
  if (year < 1950 || year > thisYear) {
    return bad("bad_year", `“${yearStr}” isn't a plausible year of issue.`, dl);
  }

  return { valid: true, normalized: dl, stateCode, state, rtoCode, year };
}

/* ── Passport ────────────────────────────────────────────────────────────── */

const PASSPORT_RE = /^[A-PR-WY][0-9]{7}$/;

export type PassportErrorCode = "empty" | "wrong_length" | "bad_shape";

/**
 * Indian passports are one letter then seven digits. The letters Q, X and Z are
 * not used as the leading character, which is a cheap extra typo check.
 */
export function validatePassport(input: string): IdResult<PassportErrorCode> {
  const id = upper(input);
  if (!input.trim()) return bad("empty", "Enter a passport number.", id);
  if (id.length !== 8) {
    return bad(
      "wrong_length",
      `A passport number is 8 characters — ${id.length} so far.`,
      id,
    );
  }
  if (!PASSPORT_RE.test(id)) {
    return bad(
      "bad_shape",
      "A passport number looks like A1234567 — one letter, seven digits.",
      id,
    );
  }
  return ok(id);
}

/**
 * Indian vehicle registration number validation.
 *
 * Two live formats:
 *
 *   State series   MH 12 AB 1234   state + RTO district + series + number
 *   Bharat (BH)    22 BH 1234 AA   year + "BH" + number + series
 *
 * The BH series was introduced in 2021 for vehicles that move between states,
 * and its digits-first shape breaks any regex written only for the classic
 * format — which is why plenty of Indian insurance forms still reject it.
 */

const STATE_SERIES_RE = /^([A-Z]{2})(\d{1,2})([A-Z]{1,3})(\d{1,4})$/;
const BH_SERIES_RE = /^(\d{2})(BH)(\d{4})([A-Z]{1,2})$/;

export const RTO_STATE_CODES: Readonly<Record<string, string>> = {
  AP: "Andhra Pradesh",
  AR: "Arunachal Pradesh",
  AS: "Assam",
  BR: "Bihar",
  CG: "Chhattisgarh",
  CH: "Chandigarh",
  DD: "Daman & Diu",
  DL: "Delhi",
  DN: "Dadra & Nagar Haveli",
  GA: "Goa",
  GJ: "Gujarat",
  HP: "Himachal Pradesh",
  HR: "Haryana",
  JH: "Jharkhand",
  JK: "Jammu & Kashmir",
  KA: "Karnataka",
  KL: "Kerala",
  LA: "Ladakh",
  LD: "Lakshadweep",
  MH: "Maharashtra",
  ML: "Meghalaya",
  MN: "Manipur",
  MP: "Madhya Pradesh",
  MZ: "Mizoram",
  NL: "Nagaland",
  OD: "Odisha",
  OR: "Odisha (old code)",
  PB: "Punjab",
  PY: "Puducherry",
  RJ: "Rajasthan",
  SK: "Sikkim",
  TN: "Tamil Nadu",
  TR: "Tripura",
  TS: "Telangana",
  UK: "Uttarakhand",
  UA: "Uttarakhand (old code)",
  UP: "Uttar Pradesh",
  WB: "West Bengal",
  AN: "Andaman & Nicobar Islands",
};

export type VehicleFormat = "state" | "bharat";

export type VehicleErrorCode =
  | "empty"
  | "too_short"
  | "bad_shape"
  | "unknown_state";

export interface VehicleResult {
  valid: boolean;
  normalized: string;
  format?: VehicleFormat;
  stateCode?: string;
  state?: string;
  /** RTO district number — state format only. */
  districtCode?: string;
  series?: string;
  number?: string;
  /** Registration year — BH series only. */
  year?: string;
  formatted?: string;
  error?: { code: VehicleErrorCode; message: string };
}

function fail(
  code: VehicleErrorCode,
  message: string,
  normalized: string,
): VehicleResult {
  return { valid: false, normalized, error: { code, message } };
}

export function normalizeVehicleNumber(input: string): string {
  return input.replace(/[\s-]/g, "").toUpperCase();
}

export function validateVehicleNumber(input: string): VehicleResult {
  const reg = normalizeVehicleNumber(input);

  if (!input.trim()) return fail("empty", "Enter a registration number.", reg);
  if (reg.length < 6) {
    return fail(
      "too_short",
      "That's too short for a registration number.",
      reg,
    );
  }

  const bh = BH_SERIES_RE.exec(reg);
  if (bh) {
    const [, year, , number, series] = bh;
    return {
      valid: true,
      normalized: reg,
      format: "bharat",
      year: `20${year}`,
      number,
      series,
      formatted: `${year} BH ${number} ${series}`,
    };
  }

  const state = STATE_SERIES_RE.exec(reg);
  if (!state) {
    return fail(
      "bad_shape",
      "Use MH12AB1234, or 22BH1234AA for a Bharat series plate.",
      reg,
    );
  }

  const [, stateCode, districtCode, series, number] = state;
  const stateName = RTO_STATE_CODES[stateCode];
  if (!stateName) {
    return fail(
      "unknown_state",
      `“${stateCode}” isn't a state code we recognise.`,
      reg,
    );
  }

  return {
    valid: true,
    normalized: reg,
    format: "state",
    stateCode,
    state: stateName,
    districtCode,
    series,
    number,
    formatted: `${stateCode} ${districtCode} ${series} ${number}`,
  };
}
